-- AMKA: 001, 007, 013, 019, 025, 031, 037, 043, 049, 055, 061, 067, 073, 077
-- ======================================================================


-- ======================================================================
-- 2. ΣΤΕΛΕΧΩΣΗ ΤΕΠ (Επειγοντολόγοι) - 18 Ιατροί (Σύνολο 18)
-- Παίρνουμε Επιμελητές/Ειδικευόμενους από διάφορες ειδικότητες
-- ======================================================================
UPDATE Doctors SET specialty = 'Επειγοντολόγος' WHERE amka IN (
    '80000000002', '80000000003', -- Από Παθολόγους
    '80000000014', '80000000015', -- Από Καρδιολόγους
    '80000000020', '80000000021', -- Από Παιδιάτρους
    '80000000026', '80000000027', -- Από Γυναικολόγους
    '80000000032', '80000000033', -- Από Ορθοπεδικούς
    '80000000038', '80000000039', -- Από Ουρολόγους
    '80000000044', '80000000045', -- Από Οφθαλμιάτρους
    '80000000050', '80000000051', -- Από ΩΡΛ
    '80000000056', '80000000057'  -- Από Νευρολόγους
);


-- ======================================================================
-- 3. ΣΤΕΛΕΧΩΣΗ ΧΕΙΡΟΥΡΓΕΙΟΥ (24/7) - 18 Ιατροί (Μαζί με τον Διευθ. 007 = 19)
-- ======================================================================
UPDATE Doctors SET specialty = 'Χειρουργός' WHERE amka IN (
    -- Κρατάμε τους υπάρχοντες Χειρουργούς (εκτός του Διευθυντή που μένει)
    '80000000008', '80000000009', '80000000010', '80000000011', '80000000012',
    -- Προσθέτουμε κι άλλους
    '80000000062', '80000000063', -- Από Δερματολόγους
    '80000000068', '80000000069', -- Από Ψυχιάτρους
    '80000000074', '80000000075', '80000000076', -- Από Εντατικολόγους
    '80000000078', '80000000079', '80000000080', -- Από Ακτινολόγους
    '80000000004', '80000000005', '80000000006'  -- Από Παθολόγους
);


-- ======================================================================
-- 4. ΣΤΕΛΕΧΩΣΗ ΠΑΘΟΛΟΓΙΚΟΥ (10 Ιατροί μαζί με τον Διευθ. 001)
-- Επαρκούν για να λειτουργεί το Παθολογικό π.χ. Πρωί και Απόγευμα (2 βάρδιες)
-- ======================================================================
UPDATE Doctors SET specialty = 'Παθολόγος' WHERE amka IN (
    '80000000016', '80000000017', '80000000018', -- Από Καρδιολόγους
    '80000000022', '80000000023', '80000000024', -- Από Παιδιάτρους
    '80000000028', '80000000029', '80000000030'  -- Από Γυναικολόγους
);


-- ======================================================================
-- 5. ΣΤΕΛΕΧΩΣΗ ΜΕΘ (10 Ιατροί μαζί με τον Διευθ. 073)
-- Επαρκούν για να λειτουργεί η ΜΕΘ π.χ. Πρωί και Απόγευμα (ή να μειωθούν οι κλίνες)
-- Προσοχή: Αν θες η ΜΕΘ να είναι 24/7 χρειάζεται 19 ιατρούς. Εδώ δεν φτάνουν τα άτομα αν θες 24/7 ΤΕΠ και Χειρουργείο.
-- ======================================================================
UPDATE Doctors SET specialty = 'Εντατικολόγος' WHERE amka IN (
    '80000000034', '80000000035', '80000000036', -- Από Ορθοπεδικούς
    '80000000040', '80000000041', '80000000042', -- Από Ουρολόγους
    '80000000046', '80000000047', '80000000048'  -- Από Οφθαλμιάτρους
);

