-- ============================================================================
-- ΕΙΣΑΓΩΓΗ ΜΕ ΔΥΝΑΜΙΚΗ ΑΝΑΘΕΣΗ ΙΑΤΡΩΝ ΚΑΙ ΗΜΕΡΟΜΗΝΙΩΝ 
-- (Ώστε να περάσουν τον έλεγχο του Trigger)
-- ============================================================================


-- 1. Μεταμόσχευση ήπατος (Dept 2 - Χειρουργικό)
SELECT 1, 1, d.amka, 1, 'Χειρουργική', 'Μεταμόσχευση ήπατος', CONCAT(s.shift_date, ' 08:00:00'), 45, 28907
FROM Shift s JOIN Shift_Staff ss ON s.shift_id = ss.shift_id JOIN Doctors d ON ss.staff_amka = d.amka
WHERE s.department_id = 2 AND s.shift_type = 'morning' AND YEAR(s.shift_date) IN (2024, 2025, 2026) ORDER BY RAND() LIMIT 1;

-- 2. Μεταμόσχευση καρδιάς-πνευμόνων (Dept 2 - Χειρουργικό)
SELECT 2, 2, d.amka, 2, 'Χειρουργική', 'Μεταμόσχευση καρδιάς-πνευμόνων', CONCAT(s.shift_date, ' 08:30:00'), 60, 50379
FROM Shift s JOIN Shift_Staff ss ON s.shift_id = ss.shift_id JOIN Doctors d ON ss.staff_amka = d.amka
WHERE s.department_id = 2 AND s.shift_type = 'morning' AND YEAR(s.shift_date) IN (2024, 2025, 2026) ORDER BY RAND() LIMIT 1;

-- 3. Μεταμοσχεύσεις Πνευμόνων (Dept 1 - Παθολογικό/Θεραπευτικό)
SELECT 3, 3, d.amka, 3, 'Θεραπευτική', 'Μεταμοσχεύσεις Πνευμόνων', CONCAT(s.shift_date, ' 09:00:00'), 30, 30015
FROM Shift s JOIN Shift_Staff ss ON s.shift_id = ss.shift_id JOIN Doctors d ON ss.staff_amka = d.amka
WHERE s.department_id = 1 AND s.shift_type = 'morning' AND YEAR(s.shift_date) IN (2024, 2025, 2026) ORDER BY RAND() LIMIT 1;

-- 4. Μεταμόσχευση Καρδιάς (Dept 2 - Χειρουργικό)
SELECT 4, 4, d.amka, 4, 'Χειρουργική', 'Μεταμόσχευση Καρδιάς', CONCAT(s.shift_date, ' 09:30:00'), 90, 34279
FROM Shift s JOIN Shift_Staff ss ON s.shift_id = ss.shift_id JOIN Doctors d ON ss.staff_amka = d.amka
WHERE s.department_id = 2 AND s.shift_type = 'morning' AND YEAR(s.shift_date) IN (2024, 2025, 2026) ORDER BY RAND() LIMIT 1;

